#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, y;
    cin >> p >> y;

    int limit = static_cast<int>(sqrtl(static_cast<long double>(y)));
    vector<bool> isPrime(limit + 1, true);
    vector<int> primes;

    if (limit >= 0) isPrime[0] = false;
    if (limit >= 1) isPrime[1] = false;

    for (int i = 2; i <= limit; ++i) {
        if (!isPrime[i]) continue;
        primes.push_back(i);
        if (1LL * i * i <= limit) {
            for (ll j = 1LL * i * i; j <= limit; j += i) {
                isPrime[j] = false;
            }
        }
    }

    for (ll x = y; x > p; --x) {
        bool valid = true;
        for (int prime : primes) {
            if (prime > p || 1LL * prime * prime > x) break;
            if (x % prime == 0) {
                valid = false;
                break;
            }
        }

        if (valid) {
            cout << x << '\n';
            return 0;
        }
    }

    cout << -1 << '\n';
    return 0;
}

